static void USB_SetSuspendM(void)
{
	*(volatile unsigned int *)(USB_CONFIG_BASE + CONFIG_USB1_CONFIG) &= ~(1<<10);
	*(volatile unsigned int *)(USB_CONFIG_BASE + CONFIG_USB1_CONFIG) &= ~(1<<26);
	*(volatile unsigned int *)(USB_CONFIG_BASE + CONFIG_USB2_CONFIG) &= ~(1<<26);
}

static void USB_ClrSuspendM(void)
{
	*(volatile unsigned int *)(USB_CONFIG_BASE + CONFIG_USB1_CONFIG) |= (1<<10);
	*(volatile unsigned int *)(USB_CONFIG_BASE + CONFIG_USB1_CONFIG) |= (1<<26);
	*(volatile unsigned int *)(USB_CONFIG_BASE + CONFIG_USB2_CONFIG) |= (1<<26);
}

static void USB_SetPhyReset(void)
{
	*(volatile unsigned int *)(USB_CONFIG_BASE + CONFIG_USB1_CONFIG) |= (1<<12);
	*(volatile unsigned int *)(USB_CONFIG_BASE + CONFIG_USB1_CONFIG) |= (1<<28);
	*(volatile unsigned int *)(USB_CONFIG_BASE + CONFIG_USB2_CONFIG) |= (1<<28);
}

static void USB_ClrPhyReset(void)
{
	*(volatile unsigned int *)(USB_CONFIG_BASE + CONFIG_USB1_CONFIG) &= ~(1<<12);
	*(volatile unsigned int *)(USB_CONFIG_BASE + CONFIG_USB1_CONFIG) &= ~(1<<28);
	*(volatile unsigned int *)(USB_CONFIG_BASE + CONFIG_USB2_CONFIG) &= ~(1<<28);
}

static void USB_Init(void)
{
	/*                      usb phy                      */
	// LQFP
	*(volatile unsigned int*)(USB_PHY_PORT1 + 0x00) = 0x1f;
	*(volatile unsigned int*)(USB_PHY_PORT1 + 0x0c) = 0xe0;
	*(volatile unsigned int*)(USB_PHY_PORT1 + 0x14) = 0xb0;
	*(volatile unsigned int*)(USB_PHY_PORT1 + 0x18) = 0x0d;

	*(volatile unsigned int*)(USB_PHY_PORT2 + 0x00) = 0x1f;
	*(volatile unsigned int*)(USB_PHY_PORT2 + 0x0c) = 0xe0;
	*(volatile unsigned int*)(USB_PHY_PORT2 + 0x14) = 0xb0;
	*(volatile unsigned int*)(USB_PHY_PORT2 + 0x18) = 0x0d;

	/* clock 48Mhz div4 to 12Mhz */
#if 1
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG3) &= ~(1<<31);
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG3) |= (1<<31); //rst
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG3) &= ~(0x3f<<24);
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG3) |= (0x3<<24); //div to 148.5
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG3) &= ~(1<<30);
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG3) |= (1<<30); //load en
#endif
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_SOURCE_SEL2) |= 1|(1<<1)|(1<<2)|(1<<3)|(1<<4);
	//*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_SOURCE_SEL2) |= (1<<1)|(1<<2)|(1<<3)|(1<<4);

	/* usb phy port */
#if 0
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_USB_CONFIG) |= (1<<25)|(1<<31);
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_USB3_CONFIG) |= (1<<25);
#else
	*(volatile unsigned int*)(USB_CONFIG_BASE + CONFIG_USB_CONFIG)  |= (1<<25) | (1<<31) | (0x20<<8) | (0x20<<20) | (0x20<<26) | (0xf<<16);
	*(volatile unsigned int*)(USB_CONFIG_BASE + CONFIG_USB3_CONFIG) |= (1<<25) | (0x20<<20);
#endif

	USB_SetSuspendM();
	USB_SetPhyReset();
	USB_ClrPhyReset();
	USB_ClrSuspendM();
	USB_SetSuspendM();
	USB_SetPhyReset();
	USB_ClrPhyReset();
}

static void close_macrovision(void)
{
	*(volatile unsigned int*)(GX_REG_VIRTUAL_BASE1 + MACROVISION_CTRL0) = 0;
	*(volatile unsigned int*)(GX_REG_VIRTUAL_BASE1 + MACROVISION_CTRL1) = 0;
	*(volatile unsigned int*)(GX_REG_VIRTUAL_BASE1 + MACROVISION_CTRL2) = 0;
	*(volatile unsigned int*)(GX_REG_VIRTUAL_BASE1 + MACROVISION_CTRL3) = 0;
}

