static void hdmi_disable (void)
{
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_MPEG_CLK_INHIBIT1_NORM ) |= 1 << 5; // close hdmi clock
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_MPEG_HOT_RST_NORM) = (1 << 7); //  hdmi reset release
}

static void hdmi_enable(void)
{
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_MPEG_CLK_INHIBIT1_NORM ) &= ~(1 << 5); // enable hdmi clock
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_MPEG_HOT_RST_NORM) &= ~(1 << 7); //  hdmi reset
}

static void eth_disable (void)
{
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_MPEG_CLK_INHIBIT1_NORM ) |= 1 << 26; // close mac clock
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_MPEG_CLK_INHIBIT2_NORM ) |= 1 << 9; // close eth clock
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_MPEG_HOT_RST_NORM) = (1 << 8); //  eth reset release
}

static void eth_enable(void)
{
	unsigned char cfg = 0;
	unsigned int eth_config;

	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_MPEG_CLK_INHIBIT2_NORM ) &= ~(1 << 9); // enable eth clock
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_MPEG_HOT_RST_NORM) &= ~(1 << 8); //  eth reset
	/************** ETH clock ****************/
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG3) &= ~(1<<23);
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG3) |= (1<<23); //rst
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG3) &= ~(0x3f<<16);
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG3) |= (43<<16); //div to 44 27M
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG3) &= ~(1<<22);
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG3) |= (1<<22); //load en
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_SOURCE_SEL2) &= ~(1<<22); // set eth phy from xtal to DTO div


//	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_SOURCE_SEL) &= ~(1<<28); // set eth phy from xtal to DTO div
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_SOURCE_SEL2) &= ~(1<<23); // set eth phy from xtal to DTO div
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_SOURCE_SEL2) &= ~(1<<24); // set eth phy from xtal to DTO div

	//ETH PHY set
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_EPHY_CONFIG) |= (0x1<<23); // 0 shut down, fixe en zero
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_EPHY_CONFIG) &= ~(0x3<<0); // 0 shut down, fixe en zero
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_EPHY_CONFIG) &= ~(0x3<<9); // 0 norm mode

	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_EPHY_CONFIG) &= ~(0x3<<7); // 0 mode select
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_EPHY_CONFIG) |=  (0x2<<7); // 10 internal rmii and SMI

	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_EPHY_CONFIG) &= ~(0x7<<4); // 0 27M clock
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_EPHY_CONFIG) |=  (0x5<<4); // 10

	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_EPHY_CONFIG) &= ~(0x1f<<11); // 0 phy address
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_EPHY_CONFIG) |=  (0x1<<11); // 10

	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_EPHY_CONFIG) &= ~(0x1<<3); // 0  ephy_led_pol

	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_EPHY_CONFIG) &= ~(0xf<<16); // 0 BGS

#if 0
	gx_otp_read(0x368,1,&cfg); // to be check
	if (cfg&(1<<4))
		cfg &= 0xf;
	else
		cfg = 0x7;
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_EPHY_CONFIG) |=  (cfg<<16); // 10 BGS set
#else
	cfg = 0x7;
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_EPHY_CONFIG) |=  (cfg<<16); // 10 BGS set
#endif

	//PHY rest
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_EPHY_CONFIG) &= ~(1<<2); // select from not xtal
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_EPHY_CONFIG) |= (1<<2); // select from not xtal

	//rmii_clk
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_SOURCE_SEL) |= (1<<26); // select from not xtal
	// mii clcok
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_SOURCE_SEL2) |= (1<<30); // select from not xtal
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_SOURCE_SEL2) |= (1<<31); // select from not xtal

	// phy interface select
	eth_config = *(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_ETH_CONFIG);
	eth_config |= 0x100;
	eth_config &= ~0xc0;
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_ETH_CONFIG) = eth_config; // RMII
}

static void dvb_disable(void)
{
	//close dem_clk_H
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_SOURCE_SEL) &= ~(1<<30); // select from xtal
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG2) &= ~(1<<12);

	//close fec_clk
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_SOURCE_SEL) &= ~(1<<29); // select from xtal
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG2) &= ~(1<<21);

	//close adc clk
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_SOURCE_SEL) &= ~(1<<27); // select from xtal
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG2) &= ~(1<<30);
        //close adc ip
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_ADC_CONFIG_0) &= ~((0x3<<18) | (0x1<<8) ); // adc in power down mode endacr is 0
}

static void dvb_enable(void)
{
#ifdef DVB_CHANNEL_S2
	// DIV for dvbs 1
	//dem_clk_H 1188 div10 118.8Mhz
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG2) &= ~(1<<12);
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG2) |= (1<<12); //rst
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG2) &= ~(0x3f<<4);
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG2) |= (9<<4); //div
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG2) &= ~(1<<11);
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG2) |= (1<<11); //load en

	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_SOURCE_SEL) |= (1<<30); // select from not xtal

	//fec_clk 1188 div8 to 148.5MHz
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG2) &= ~(1<<21);
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG2) |= (1<<21); //rst
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG2) &= ~(0x3f<<13);
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG2) |= (7<<13); //div to
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG2) &= ~(1<<20);
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG2) |= (1<<20); //load en

	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_SOURCE_SEL) |= (1<<29); // select from not xtal

	//When DVBS use the ADC clock for 237.6MHz
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG2) &= ~(1<<30);
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG2) |= (1<<30); //rst
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG2) &= ~(0x3f<<22);
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG2) |= (4<<22);
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG2) &= ~(1<<29);
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG2) |= (1<<29); //load en

	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_SOURCE_SEL) |= (1<<27); // select from not xtal to div

	//adc clock
	//doube mode[19:18] 00 10 xtal  01 div clock 11 div2 of the div clok
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_SOURCE_SEL2) &= ~(0x3<<18); // select from not xtal
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_SOURCE_SEL2) |= (0x1<<18); // select 01 doube of dvbs clok

	// dvb module adc clok
	// to adc clock inv
	// *(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_SOURCE_SEL2) |= (0x1<<10); // select 00 doube of dvbs clok
	//not inv
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_SOURCE_SEL2) |= (0x1<<10); //

	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_SOURCE_SEL) |= (0x1<<31); // xtal to PLL adc
	//adc set

	//set the  fsctrl
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_ADC_CONFIG_0) &= ~(0xff<<10); // fsctrl 000is 1x 11111111 = 1.996x
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_ADC_CONFIG_0) |= (0x10<<10); // fsctrl 000is 1x 11111111 = 1.996x
	//bctrl 00110
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_ADC_CONFIG_0) &= ~(0x1f<<2);
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_ADC_CONFIG_0) |= (0x6<<2); ///70%

	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_ADC_CONFIG_0) &= ~(0x1f<<24); // set i2c address
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_ADC_CONFIG_0) |=  (0x1d<<24); // set i2c address //1d << 2 address is 74
	//set the scl and sda is high
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_ADC_CONFIG_0) |=  (0x7<<29); // set scl and sdi and i2c resetz go high

	// when power down . adc is in power down  mode set opm =00;

	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_ADC_CONFIG_0) &= ~((0x3<<18) | (0x1<<8) ); // adc in power down mode endacr is 0
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_ADC_CONFIG_0) |= (1<<8); // endcr disable the duty cycle restorer

	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_ADC_CONFIG_0) &=  ~(0x3<<22); // use_prev_f is zero ,powerup need the use_prev_f, startcal set zero, power auto starcal

	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_ADC_CONFIG_0) &= ~(0x1<<29); // i2c resetz set low keep at leas 4ns
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_ADC_CONFIG_0) |=  (0x1<<29); // i2c resetz set hihgh no is

	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_ADC_CONFIG_0) |=  (0x3<<18); // i2c resetz set hihgh no is
	// set to the normal mode
	//do {
	//	adc_rdy = (*(volatile unsigned int*)(CONFIG_BASE_MMU+STATE_ADC))& 0x2 ; // [1] bit is adcrdy
	//} while (!(adc_rdy & 0x2));
	// set the port
	// DVBS set the duble I and q

	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_ADC_CONFIG_0) |=  (0x1<<7) |(0x1<<20) ; // i2c resetz set hihgh no is
	//end

#endif

#ifdef DVB_CHANNEL_C
	//When DVBC use the DAC clock for 29.7, DVBC clock to 59.4 so there is 59.4
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG2) &= ~(1<<30);
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG2) |= (1<<30); //rst
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG2) &= ~(0x3f<<22);
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG2) |= (19<<22); //div 20 to 59.4M
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG2) &= ~(1<<29);
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG2) |= (1<<29); //load en

	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_SOURCE_SEL) |= (1<<27); // select from not xtal

	//adc clock
	//doube mode[19:18] 00 10 xtal  01 div clock 11 div2 of the div clok
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_SOURCE_SEL2) &= ~(0x3<<18); // select from not xtal
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_SOURCE_SEL2) |= (0x3<<18); // select div 2 of dvbc for adc clock is 29.7M

	// dvb module adc clok
	// to adc clock inv
	// *(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_SOURCE_SEL2) |= (0x1<<10); // select 00 doube of dvbs clok
	//not inv
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_SOURCE_SEL2) |= (0x1<<10); // select 00 doube of dvbs clok

	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_SOURCE_SEL) |= (0x1<<31); // xtal to PLL adc

	//set the  fsctrl
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_ADC_CONFIG_0) &= ~(0xff<<10); // fsctrl 000is 1x 11111111 = 1.996x
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_ADC_CONFIG_0) |= (0x10<<10);
	//bctrl 00110
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_ADC_CONFIG_0) &= ~(0x1f<<2);
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_ADC_CONFIG_0) |= (0x6<<2); ///70%


	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_ADC_CONFIG_0) &= ~(0x1f<<24); // set i2c address
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_ADC_CONFIG_0) |=  (0x1d<<24); // set i2c address //1d << 2 address is 74
	//set the scl and sda is high
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_ADC_CONFIG_0) |=  (0x7<<29); // set scl and sdi and i2c resetz go high

	// when power down . adc is in power down  mode set opm =00;

	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_ADC_CONFIG_0) &= ~((0x3<<18) | (0x1<<8) ); // adc in power down mode endacr is 0
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_ADC_CONFIG_0) |= (1<<8); // endcr disable the duty cycle restorer

	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_ADC_CONFIG_0) &=  ~(0x3<<22); // use_prev_f is zero ,powerup need the use_prev_f, startcal set zero, power auto starcal

	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_ADC_CONFIG_0) &= ~(0x1<<29); // i2c resetz set low keep at leas 4ns
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_ADC_CONFIG_0) |=  (0x1<<29); // i2c resetz set hihgh no is

	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_ADC_CONFIG_0) |=  (0x3<<18); // i2c resetz set hihgh no is

	// set to the normal mode
	//do {
	//	adc_rdy = (*(volatile unsigned int*)(CONFIG_BASE_MMU+STATE_ADC))& 0x2 ; // [1] bit is adcrdy
	//} while (!(adc_rdy & 0x2));

	// set the port
	// DVBS set the duble I and q

	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_ADC_CONFIG_0) &= ~((0x1<<7) |(0x1<<20)) ; // one port
	//end

#endif
}

void gx_setup_pll_full_controller(void)
{
	int i;
	//unsigned int adc_rdy;

	for (i=0; i < sizeof(dto_table) / sizeof(struct pll_dto); i++) {
		if (dto_table[i].dto != 0)
			DTO_Config(dto_table[i].dto, dto_table[i].div, 1);
		if(dto_table[i].dto_sel != 0)
			*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_SOURCE_SEL) |= dto_table[i].dto_sel;
		if(dto_table[i].dto_sel2 != 0)
			*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_SOURCE_SEL2) |= dto_table[i].dto_sel2;
	}

#define USB_DEFINE   0

	// set clock_audio_decoder source from xtal to DTO
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_SOURCE_SEL) |= (1<<15);

	/************** AUDIO clock ****************/
	// clock_audio_lodac
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG) &= ~(1<<31);
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG) |= (1<<31); //rst
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG) &= ~(0x3f<<23);
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG) |= (23<<23); //div//(23 + 1)分频、、1188/24=49.5M
	//*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG) |= (11<<23); //div//(11 + 1)分频、、1188/12=99M
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG) &= ~(1<<30);
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG) |= (1<<30); //load end
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_SOURCE_SEL) |= (1<<0);// set clock_audio_lodac source from xtal to DTO div
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_SOURCE_SEL) |= (1<<1);// set clock_srl_audio_play source from clock_spd_audio_play to DTO
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_SOURCE_SEL) |= (1<<2);// set clock_spd_audio_play source from xtal to DTO

	/************** VPU (VIDEOO  PIXEL) clock ****************/
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG) &= ~(1<<6);
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG) |= (1<<6); //rst
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG) &= ~(0x3f<<0);
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG) |= (0x7<<0); //7 : div6 to 198Mhz  21:div20 59Mhz  43:div42 27Mhz
											//  1080p/1080i/720p     480p/576p    cvbs(480i/576i)
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG) &= ~(1<<7);
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG) |= (1<<7); //load en
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_SOURCE_SEL) |= (1<<5); // set clock_pll_pixel_double source from xtal to DTO div
	// div for clock_hdmi/clock_video_pixel_dcs/clock_video_pixel
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG) &= ~(0x7<<8);
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG) |= (0x5<<8); //480i/576i  3'b011 576p/480p/720p/1080i/1080p 3'b101
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG) &= ~(0x1<<11);   //rst
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG) |= (0x1<<11);

#ifdef CONFIG_CLOCK_HDMI_DISABLE
	hdmi_disable();
#else
	hdmi_enable();
#endif

	/************** SVPU (VIDEO PIXEL1) clock ****************/
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG) &= ~(1<<20);
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG) |= (1<<20); //rst
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG) &= ~(0x3f<<12);
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG) |= (0x2a<<12); //div to 27
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG) &= ~(1<<19);
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG) |= (1<<19); //load en
#ifdef CONFIG_24M_XTAL
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_SOURCE_SEL) |= (1<<6); // set clock_pll_pixel1_double source from xtal to DTO div
#else
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_SOURCE_SEL) &= ~(1<<6); //set clock_pll_pixel1_double source to xtal
#endif
	// div for the clock_video_pixel1
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG4) &= ~(0x3<<0);
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG4) |= (0x3<<0);
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG4) &= ~(0x1<<2);   //rst
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG4) |= (0x1<<2);
	//HDMI  clock_hdmi_icec clock select 33Khz
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_SOURCE_SEL2) |= (0x1<<5); // set clock_hdmi_icec source from xtal to clock_hdmi_icec
	//dcs pixel pixdel double hdmi hdmi phy hdmi icec hdmi sfr

	/************** VIDEO DAC clock ****************/
	// dac clock come from pixel doule or ivnv of double
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_SOURCE_SEL2) &= ~(0x1<<6);//ypbpr/ycbcr use the inv of the pixel doubleclock
	// dac clock come from pixel1 doule or ivnv of double
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_SOURCE_SEL2) &= ~(0x1<<7);//cvbs use the inv of the pixel doubleclock
	//dac1 0 from pixel 1 from pixel1 default as Y PORT
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_SOURCE_SEL) &= ~(1<<8); // select from not xtal
	//dac2 0 from pixel 1 from pixel1 default as Pb PORT
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_SOURCE_SEL) &= ~(1<<9); // select from not xtal
	//dac3 0 from pixel 1 from pixel1 default as Pr PORT
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_SOURCE_SEL) &= ~(1<<10); // select from not xtal
	//dac4 0 from pixel 1 from pixel1 default as cvbs port
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_SOURCE_SEL) |= (1<<11); // select from not xtal
	//end the video dac

	/************** TS clock ****************/
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_SOURCE_SEL3) |= (1<<0);//ts0 from xtal to ts clk
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_SOURCE_SEL3) |= (1<<1);//ts1 from xtal to ts clk
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_SOURCE_SEL3) |= (1<<2);//ts2 from xtal to ts clk
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_SOURCE_SEL3) |= (1<<3);//ts3 from xtal to ts clk

	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_SOURCE_SEL3) |= (1<<4);//ts0 use ts clk negedge
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_SOURCE_SEL3) |= (1<<5);//ts1 use ts clk negedge
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_SOURCE_SEL3) |= (1<<6);//ts2 use ts clk negedge
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_SOURCE_SEL3) |= (1<<7);//ts3 use ts clk negedge

#if USB_DEFINE
	/************** USB clock ****************/
	// USB use DTO div 99 to get the clock , not need set
	//*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_SOURCE_SEL2) |= (1<<0); // set usb source from xtal to DTO div
	// usb mac clock
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_SOURCE_SEL2) |= (1<<1); // set usb mac source from xtal to usb mac row
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_SOURCE_SEL2) |= (1<<2); // set usb mac1 source from xtal to usb mac1 row
	// usb 48M
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_SOURCE_SEL2) |= (1<<3); // set usb 48m source from xtal to usb 48m row
	//usb 12M
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG3) &= ~(1<<31);
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG3) |= (1<<31); //rst
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG3) &= ~(0x3f<<24);
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG3) |= (0x3<<24); //div to 148.5
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG3) &= ~(1<<30);
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_CLOCK_DIV_CONFIG3) |= (1<<30); //load en
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_SOURCE_SEL2) |= (1<<4); // set usb 12m source from xtal to usb 12m row
#endif

#ifdef CONFIG_CLOCK_ETH_DISABLE
	eth_disable();
#else
	eth_enable();
#endif

#ifdef CONFIG_CLOCK_DVB_DISABLE
	dvb_disable();
#else
	dvb_enable();
#endif
	//video dac
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_DAC_CONFIG_0) &= ~(0x1<<0);	//enextref set zero
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_DAC_CONFIG_0) |= (0x1<<1);	//envbg set high
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_DAC_CONFIG_0) &= ~(0x7<<4);	//enctr set zero
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_DAC_CONFIG_0) &= ~(0xf<<8);	//ensc set zero

	close_macrovision();
	USB_Init();

#ifdef ENABLE_SECURE_ALIGN
	// usb
	*(volatile unsigned int*)(USB_CONFIG_BASE + CONFIG_USB3_CONFIG) |= 1;
	// demux
	*(volatile unsigned int*)(REG_BASE_DEMUX + 0x47F0) &= ~0x3;
	*(volatile unsigned int*)(REG_BASE_DEMUX + 0x47F0) |= 0x3;
	// gp
	*(volatile unsigned int*)(REG_BASE_GP) |= (1<<5);
	// audio_or
	*(volatile unsigned int*)(REG_BASE_AUDIO_OR + 0x1EC) &= ~(0x3 << 1);
	*(volatile unsigned int*)(REG_BASE_AUDIO_OR + 0x1EC) |= (0x2 << 1);
	// ga
	*(volatile unsigned int*)(REG_BASE_GA + 0x34) |= 1;
	// m2m
	*(volatile unsigned int*)(REG_BASE_M2M + 0x2400) |= 1;
#endif

	/* close firewall */
	*(volatile unsigned int *)(REG_BASE_FIREWALL) = 0x0; // disable enable all instance & hide default filter
	*(volatile unsigned int *)(REG_BASE_FIREWALL + 0x200) = 0xffffffff;
	*(volatile unsigned int *)(REG_BASE_FIREWALL + 0x204) = 0xffffffff;
	*(volatile unsigned int *)(REG_BASE_FIREWALL + 0x300) = 0x01; // Upload reg config

	/* modify DDCSCL DDCSDA driver strength, CONFIG_IO_DRIVE_CTL1[9:10]: 00-6.6mA, 01-13.3mA, 10-19.9mA, 11-26.5mA */
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_IO_DRIVE_CTL1) &= ~(3 << 9);
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_IO_DRIVE_CTL1) |= 1 << 9;
}
